#include "../msgpack.h"
#include "test_harness.h"
#include <stdbool.h>
#include <stddef.h>
#include <string.h>

TEST(test_msgpack_enc_nil_sentinel) {
    uint8_t backing[64];
    memset(backing, 0xFF, sizeof(backing));
    msgpack_enc_t enc;
    msgpack_enc_init(&enc, backing, sizeof(backing));
    msgpack_enc_nil(&enc);
    size_t used = msgpack_enc_len(&enc);
    /* sentinel: byte after encoded data must be untouched */
    if (used > 0 && used < sizeof(backing)) {
        ASSERT_EQ(backing[used], 0xFF);
    }
}

